const http = require('http');

http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/plain' });
  if (req.url === '/') {
    res.end('Home page');
  } else if (req.url === '/about') {
    res.end('About page');
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
}).listen(3000);

